from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    occupied={(r,c) for r in range(h) for c in range(w) if grid[r][c]==2}
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color in (0,2) or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                x,y=q.pop(); cells.append((x,y))
                for p in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    a,b=p
                    if 0<=a<h and 0<=b<w and p not in seen and grid[a][b]==color:
                        seen.add(p); q.append(p)
            comps.append((color,cells))
    comps.sort(key=lambda z:min(r for r,c in z[1]))
    out=[[0]*w for _ in range(h)]
    for r,c in occupied: out[r][c]=2
    for color,cells in comps:
        shift=0
        while True:
            candidate={(r-shift-1,c) for r,c in cells}
            if min(r for r,c in candidate)<0 or candidate & occupied: break
            shift+=1
        for r,c in cells:
            out[r-shift][c]=color
            occupied.add((r-shift,c))
    return out

