def transform(grid):
    h,w=len(grid),len(grid[0])
    barriers={(r,c) for r in range(h) for c in range(w) if grid[r][c]==2}
    up = sum(r for r,c in barriers)/len(barriers) < (h-1)/2
    occupied=set(barriers)
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color in (0,2) or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                x,y=q.pop(); cells.append((x,y))
                for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==color:
                        seen.add((a,b)); q.append((a,b))
            comps.append((color,cells))
    comps.sort(key=lambda z:(min(r for r,c in z[1]) if up else -max(r for r,c in z[1])))
    out=[[0]*w for _ in range(h)]
    for r,c in barriers: out[r][c]=2
    dr=-1 if up else 1
    for color,cells in comps:
        shift=0
        while True:
            cand={(r+dr*(shift+1),c) for r,c in cells}
            if any(r<0 or r>=h for r,c in cand) or cand & occupied: break
            shift+=1
        for r,c in cells:
            nr=r+dr*shift
            out[nr][c]=color; occupied.add((nr,c))
    return out

